def uebersetze(text, sprache, zeichen, pfeil, pfeil_runter):
    for de, ziel in BLOECKE[sprache]:
        text = text.replace(de, ziel)
    for de, ziel in sorted(T[sprache].items(), key=lambda x: -len(x[0])):
        text = text.replace(">" + de + "<", ">" + ziel + "<").replace(">" + de + " {{", ">" + ziel + " {{").replace('="' + de + '"', '="' + ziel + '"').replace(">" + de + ' <', ">" + ziel + ' <')
    text = text.replace('<html lang="de">', f'<html lang="{sprache}">')
    # Pfade: eigene Seiten bleiben, alles andere eine Ebene höher
    text = re.sub(r'(?<![\w./])(media|schrift)/', r'../\1/', text)
    text = re.sub(r'(href|src)="(seite\.css|seite\.js|favicon\.png)"', r'\1="../\2"', text)
    text = re.sub(r'href="(uebungen|angehoerige|fragen|unternehmen|anamnese|impressum|datenschutz)\.html', r'href="../\1.html', text)
    wo = "ueber" if "Über mich ·" in text or 'id="geschichte"' in text else "start"
    nav = "".join(f'<a{" class=\"hier\"" if (wo=="ueber" and h=="ueber-mich.html") else ""} href="{h}">{t}</a>' for h, t in NAV[sprache])
    leiste = f'<header class="leiste" id="leiste">\n  <a class="marke" href="index.html">{zeichen}<span>Sylvia Sroka</span></a>\n  <nav>{nav}<a class="ruf" href="tel:+495112607414">+49 511 260 74 14</a></nav>\n</header>'
    fuss = '<footer class="fuss">\n  <a class="marke" href="index.html">' + zeichen + ('Physiotherapy Sylvia Sroka' if sprache == "en" else 'Fisioterapia Sylvia Sroka') + '</a>\n  <nav>' + "".join(f'<a href="{h}">{t}</a>' for h, t in FUSS[sprache]) + '</nav>\n</footer>'
    text = re.sub(r"\{\{LEISTE:\w+\}\}", leiste, text).replace("{{FUSS}}", fuss)
    return text.replace("{{ZEICHEN}}", zeichen).replace("{{PFEIL}}", pfeil).replace("{{PFEIL_RUNTER}}", pfeil_runter)

def baue(zeichen, pfeil, pfeil_runter):
    for sprache in ["en", "es"]:
        (hier / sprache).mkdir(exist_ok=True)
        for seite in ["index", "ueber-mich"]:
            (hier / sprache / f"{seite}.html").write_text(uebersetze((hier / f"{seite}.src.html").read_text(), sprache, zeichen, pfeil, pfeil_runter))
